import React from 'react';
import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export interface CardProps extends React.HTMLAttributes<HTMLDivElement> {
  glow?: 'none' | 'primary' | 'success' | 'warning' | 'danger';
  hoverable?: boolean;
}

export const Card = React.forwardRef<HTMLDivElement, CardProps>(
  ({ className, glow = 'none', hoverable = false, children, ...props }, ref) => {
    const glows = {
      none: '',
      primary: 'shadow-glow-primary border-primary/20 dark:border-primary/30',
      success: 'shadow-glow-success border-success/20 dark:border-success/30',
      warning: 'shadow-glow-warning border-warning/20 dark:border-warning/30',
      danger: 'shadow-glow-danger border-danger/20 dark:border-danger/30',
    };

    return (
      <div
        ref={ref}
        className={cn(
          'bg-card border border-subtle rounded-2xl p-6 transition-all duration-300 shadow-sm relative overflow-hidden',
          hoverable && 'hover:shadow-md hover:border-primary/40 dark:hover:border-primary/50 hover:-translate-y-0.5',
          glows[glow],
          className
        )}
        {...props}
      >
        {children}
      </div>
    );
  }
);

Card.displayName = 'Card';
