import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { Calendar } from 'lucide-react';
import clsx from 'clsx';
import { getTrainSupportedClasses, getDefaultActiveClass } from '../../utils/trainClasses';
import { classifyAvailability } from '../../utils/availabilityClassifier';

export const QUOTA_FULL_LABELS: Record<string, string> = {
  GN: 'GENERAL',
  TQ: 'TATKAL',
  LD: 'LADIES',
  SS: 'SENIOR CITIZEN',
};

export const QUOTA_DISPLAY_NAMES: Record<string, string> = {
  GN: 'General',
  TQ: 'Tatkal',
  LD: 'Ladies',
  SS: 'Senior Citizen',
};

/**
 * Normalizes running_days string into a strict 7-length binary array [Sun, Mon, Tue, Wed, Thu, Fri, Sat]
 * 0 = Doesn't run on that day
 * 1 = Runs on that day
 */
export function normalizeRunningDays(days: any): number[] | null {
  if (!days) return null;
  if (Array.isArray(days)) {
    if (days.length === 7 && days.every(d => d === 0 || d === 1 || d === '0' || d === '1')) {
      return days.map(Number);
    }
  }
  if (typeof days !== 'string') return null;

  const input = days.toLowerCase().trim();
  const cleanInput = input.replace(/\s+/g, '').replace(/,/g, '');

  if (input === 'daily' || input === 'all days' || input === '0,1,2,3,4,5,6' || input.includes('all')) {
    return [1, 1, 1, 1, 1, 1, 1];
  }

  // 7-character binary string (e.g. 1111111 or 1010101)
  if (cleanInput.match(/^[01]{7}$/)) {
    const raw = cleanInput.split('').map(Number);
    // IRCTC standard: [Mon, Tue, Wed, Thu, Fri, Sat, Sun] -> We convert to [Sun, Mon, Tue, Wed, Thu, Fri, Sat]
    return [raw[6], raw[0], raw[1], raw[2], raw[3], raw[4], raw[5]];
  }

  // Y/N format (e.g. YYNYNNN)
  if (cleanInput.match(/^[yn]{7}$/)) {
    const raw = cleanInput.split('').map(char => char === 'y' ? 1 : 0);
    return [raw[6], raw[0], raw[1], raw[2], raw[3], raw[4], raw[5]];
  }

  // Comma separated day indices (0=Sun, 1=Mon, ..., 6=Sat)
  const numericParts = input.includes(',') ? input.split(',').map(p => p.trim()) : (input.length === 1 ? [input] : []);
  if (numericParts.length > 0) {
    const binary = new Array(7).fill(0);
    let found = false;
    for (const part of numericParts) {
      const num = parseInt(part, 10);
      if (!isNaN(num) && num >= 0 && num <= 6) {
        binary[num] = 1;
        found = true;
      }
    }
    if (found) return binary;
  }

  // Day names map (Sun, Mon, Tue...)
  const dayMap: Record<string, number> = {
    'sun': 0, 'sunday': 0,
    'mon': 1, 'monday': 1,
    'tue': 2, 'tuesday': 2,
    'wed': 3, 'wednesday': 3,
    'thu': 4, 'thursday': 4,
    'fri': 5, 'friday': 5,
    'sat': 6, 'saturday': 6
  };
  const binary = new Array(7).fill(0);
  let matched = false;
  for (const [name, idx] of Object.entries(dayMap)) {
    if (input.includes(name)) {
      binary[idx] = 1;
      matched = true;
    }
  }
  return matched ? binary : null;
}

/**
 * Checks if a train runs on a specific date (YYYY-MM-DD)
 */
export function isTrainRunningOnDate(train: any, dateStr: string, isSearchDate: boolean = false): boolean {
  if (!dateStr) return true;
  try {
    const todayStr = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Kolkata' }).format(new Date());
    if (dateStr < todayStr) return false;

    // Check cancellation flag
    if (train?.isCancelled) return false;

    // Check runningDays metadata if available
    const rawDays = train?.runningDays || train?.running_days || train?.days || train?.scheduleDays || train?.travelDays || train?.run_days;
    if (!rawDays) {
      // FIX 2: If running days metadata is missing, DO NOT blindly query provider for adjacent dates.
      // Only allow exact search date to query live, adjacent dates remain blocked until schedule is confirmed.
      return isSearchDate;
    }

    const binary = normalizeRunningDays(rawDays);
    if (!binary) {
      return isSearchDate;
    }

    const parts = dateStr.split('-').map(Number);
    if (parts.length !== 3 || parts.some(isNaN)) return isSearchDate;

    // FIX 6: Account for dayOffset from boarding station to train origin
    const dayOffset = Number.isInteger(train?.dayOffset) ? train.dayOffset : (Number.isInteger(train?.day_offset) ? train.day_offset : 0);
    const dateObj = new Date(Date.UTC(parts[0], parts[1] - 1, parts[2] - dayOffset, 12, 0, 0));
    const dayOfWeek = dateObj.getUTCDay(); // 0 = Sun, 1 = Mon, ..., 6 = Sat

    return binary[dayOfWeek] === 1;
  } catch {
    return isSearchDate;
  }
}

/**
 * Date shifting helper (YYYY-MM-DD +/- days)
 */
function shiftDate(dStr: string, days: number): string {
  try {
    const parts = dStr.split('-').map(Number);
    if (parts.length !== 3 || parts.some(isNaN)) return dStr;
    const d = new Date(Date.UTC(parts[0], parts[1] - 1, parts[2], 12, 0, 0));
    d.setUTCDate(d.getUTCDate() + days);
    const y = d.getUTCFullYear();
    const m = String(d.getUTCMonth() + 1).padStart(2, '0');
    const day = String(d.getUTCDate()).padStart(2, '0');
    return `${y}-${m}-${day}`;
  } catch {
    return dStr;
  }
}

/**
 * Formats date into "20 AUG" format
 */
function formatPillDate(dStr: string): string {
  if (!dStr) return '';
  try {
    const parts = dStr.split('-');
    if (parts.length !== 3) return dStr;
    const months = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'];
    const day = parseInt(parts[2], 10);
    const monthIdx = parseInt(parts[1], 10) - 1;
    if (isNaN(day) || monthIdx < 0 || monthIdx > 11) return dStr;
    return `${day} ${months[monthIdx]}`;
  } catch {
    return dStr;
  }
}

/**
 * Returns 3-letter day name (e.g. "Sun", "Mon")
 */
function formatDayName(dStr: string): string {
  if (!dStr) return '';
  try {
    const parts = dStr.split('-').map(Number);
    if (parts.length !== 3 || parts.some(isNaN)) return '';
    const dateObj = new Date(Date.UTC(parts[0], parts[1] - 1, parts[2], 12, 0, 0));
    const dayNames = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
    return dayNames[dateObj.getUTCDay()];
  } catch {
    return '';
  }
}

/**
 * AvailabilityPanel: Dynamic Class-First Multi-Date Availability View
 * Primary controls: Dynamically derived based on train's authentic coaches
 * Displays multi-date availability (D-1, D, D+1, D+2) for the selected class.
 * Every date card is an independent, clickable availability action.
 */
export const AvailabilityPanel = ({
  trainNo,
  fromStn,
  toStn,
  date,
  selectedClass,
  selectedQuota = 'GN',
  availabilityMap,
  loadingTrain,
  handleCheckAvailability,
  train,
  onSelectClass,
}: {
  trainNo: string;
  fromStn: string;
  toStn: string;
  date: string;
  selectedClass: string;
  selectedQuota?: string;
  availabilityMap: any;
  loadingTrain: Record<string, boolean>;
  handleCheckAvailability: (params: any) => void;
  train?: any;
  onSelectClass?: (cls: string) => void;
}) => {
  const [failedClasses, setFailedClasses] = useState<string[]>([]);

  const supportedClasses = useMemo(() => {
    return getTrainSupportedClasses(
      {
        trainNumber: train?.trainNo || train?.trainNumber || trainNo,
        trainName: train?.trainName || train?.name,
      },
      failedClasses
    );
  }, [train, trainNo, failedClasses]);

  const [activeClass, setActiveClass] = useState<string>(() =>
    getDefaultActiveClass(supportedClasses, selectedClass)
  );

  // Keep activeClass in sync if parent selectedClass or supportedClasses change
  useEffect(() => {
    const validClass = getDefaultActiveClass(supportedClasses, selectedClass || activeClass);
    if (validClass !== activeClass) {
      setActiveClass(validClass);
    }
  }, [selectedClass, supportedClasses]);

  const baseKey = `${trainNo}_${fromStn}_${toStn}`;
  const qNorm = (selectedQuota || 'GN').toUpperCase().trim();

  // Dynamically drop classes that threw a 400 'class does not exist' error
  useEffect(() => {
    if (!availabilityMap) return;
    const detectedFailed: string[] = [];
    for (const [key, val] of Object.entries(availabilityMap)) {
      if (key.startsWith(baseKey) && val && typeof val === 'object' && 'error' in val) {
        const err = String((val as any).error || '').toLowerCase();
        if (
          err.includes('class does not exist') ||
          err.includes('invalid class') ||
          err.includes('not available for this train')
        ) {
          const parts = key.split('_');
          const cls = parts.length >= 6 ? parts[3] : parts[parts.length - 2];
          if (cls && !detectedFailed.includes(cls)) {
            detectedFailed.push(cls);
          }
        }
      }
    }
    if (detectedFailed.length > 0) {
      setFailedClasses((prev) => {
        const next = Array.from(new Set([...prev, ...detectedFailed]));
        if (next.length !== prev.length) return next;
        return prev;
      });
    }
  }, [availabilityMap, baseKey]);
  const todayStr = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Kolkata' }).format(new Date());

  // 4-day window: [D-1, D, D+1, D+2] relative to search date
  const dateWindow = [
    { offset: -1, dateStr: shiftDate(date, -1) },
    { offset: 0, dateStr: date },
    { offset: 1, dateStr: shiftDate(date, 1) },
    { offset: 2, dateStr: shiftDate(date, 2) },
  ].map(item => {
    const isPast = item.dateStr < todayStr;
    const isSearchDate = item.offset === 0;
    const isRunning = isTrainRunningOnDate(train, item.dateStr, isSearchDate);
    // Tatkal Advance Reservation Period (ARP) is 1 day.
    // If target date is more than 1 day in the future from today, Tatkal has not opened yet.
    const diffDays = Math.round((new Date(item.dateStr + 'T00:00:00Z').getTime() - new Date(todayStr + 'T00:00:00Z').getTime()) / (1000 * 60 * 60 * 24));
    const isTatkalNotOpen = qNorm === 'TQ' && diffDays > 1;
    return {
      ...item,
      formattedPill: formatPillDate(item.dateStr),
      dayName: formatDayName(item.dateStr),
      isPast,
      isRunning,
      isTatkalNotOpen,
    };
  });

  /**
   * Look up availability for a specific class and date using the
   * quota-aware cache key: trainNo_from_to_cls_date_quota (with legacy 5-part fallback).
   */
  const getAvail = useCallback((cls: string, dStr: string) => {
    const specificKey = `${baseKey}_${cls}_${dStr}_${qNorm}`;
    const specificAvail = availabilityMap[specificKey] ?? (qNorm === 'GN' ? availabilityMap[`${baseKey}_${cls}_${dStr}`] : undefined);
    if (specificAvail !== undefined) {
      if ('error' in specificAvail) return specificAvail;
      if ((specificAvail as any)[cls]) return (specificAvail as any)[cls];
      return specificAvail;
    }
    return null;
  }, [baseKey, availabilityMap, qNorm]);

  /**
   * On class selection, fetch availability for every valid date in the window.
   * Guards prevent duplicate requests and respect running/past governors.
   */
  const triggerWindowFetch = useCallback((cls: string) => {
    dateWindow.forEach(item => {
      if (!item.isPast && item.isRunning && !item.isTatkalNotOpen) {
        const availKey = `${baseKey}_${cls}_${item.dateStr}_${qNorm}`;
        const existing = getAvail(cls, item.dateStr);
        if (!existing && !loadingTrain[availKey]) {
          handleCheckAvailability({
            trainNo,
            from: fromStn,
            to: toStn,
            classType: cls,
            travelDate: item.dateStr,
            quota: qNorm,
          });
        }
      }
    });
  }, [dateWindow, baseKey, getAvail, loadingTrain, handleCheckAvailability, trainNo, fromStn, toStn, qNorm]);

  /**
   * Handles user selecting a class button.
   */
  const handleClassClick = (cls: string) => {
    setActiveClass(cls);
    if (onSelectClass) {
      onSelectClass(cls);
    }
    triggerWindowFetch(cls);
  };

  /**
   * Handles a click on a single date card. Only the clicked date is queried.
   * Past dates, dates where train is not running, and Tatkal-not-open dates are ignored.
   */
  const handleDateClick = (dItem: any) => {
    if (dItem.isPast || !dItem.isRunning || dItem.isTatkalNotOpen) return;
    const availKey = `${baseKey}_${activeClass}_${dItem.dateStr}_${qNorm}`;
    if (loadingTrain[availKey]) return;
    handleCheckAvailability({
      trainNo,
      from: fromStn,
      to: toStn,
      classType: activeClass,
      travelDate: dItem.dateStr,
      quota: qNorm,
    });
  };

  // Guard: if trainNo is missing
  if (!trainNo) return null;

  const renderCardHeader = (dItem: any) => {
    const isSearchDate = dItem.dateStr === date;
    const qLabel = QUOTA_FULL_LABELS[qNorm] || qNorm;
    return (
      <div className="flex items-center justify-between gap-1 mb-1.5">
        <div className="flex items-baseline gap-1 min-w-0">
          <span className="text-xs sm:text-sm font-black tracking-tight leading-none text-main font-mono truncate">
            {dItem.formattedPill}
          </span>
          <span className="text-[10px] font-bold uppercase tracking-wider text-muted leading-none">
            {dItem.dayName}
          </span>
        </div>
        <div className="flex items-center gap-1 shrink-0">
          <span
            className={clsx(
              "text-[7px] sm:text-[8px] font-black uppercase tracking-wider px-1.5 py-0.5 rounded-md border leading-none font-mono",
              qNorm === 'TQ' ? "bg-amber-500/10 text-amber-600 dark:text-amber-400 border-amber-500/25" :
              qNorm === 'LD' ? "bg-pink-500/10 text-pink-600 dark:text-pink-400 border-pink-500/25" :
              qNorm === 'SS' ? "bg-purple-500/10 text-purple-600 dark:text-purple-400 border-purple-500/25" :
              "bg-slate-500/10 text-slate-600 dark:text-slate-400 border-slate-500/25"
            )}
            title={`Quota: ${qLabel}`}
          >
            {qNorm}
          </span>
          {isSearchDate && (
            <span className="shrink-0 text-[7px] sm:text-[8px] font-black uppercase tracking-widest text-primary bg-primary/10 border border-primary/25 px-1.5 py-0.5 rounded-full leading-none">
              SEARCHED
            </span>
          )}
        </div>
      </div>
    );
  };

  const renderDateCard = (dItem: any) => {
    const availKey = `${baseKey}_${activeClass}_${dItem.dateStr}_${qNorm}`;
    const isLoading = !!loadingTrain[availKey];
    const val = getAvail(activeClass, dItem.dateStr) as any;
    const header = renderCardHeader(dItem);

    // ── 1. PAST DATE ──
    if (dItem.isPast) {
      return (
        <div
          key={dItem.dateStr}
          className="flex flex-col justify-between p-2.5 sm:p-3 rounded-xl sm:rounded-2xl border border-subtle/30 bg-input/10 opacity-40 select-none min-h-[96px]"
        >
          {header}
          <div className="flex-1 flex items-center justify-center">
            <span className="text-[9px] font-black uppercase tracking-widest text-muted/60">
              PAST
            </span>
          </div>
        </div>
      );
    }

    // ── 2. NOT RUNNING DATE ──
    if (!dItem.isRunning) {
      return (
        <div
          key={dItem.dateStr}
          className="flex flex-col justify-between p-2.5 sm:p-3 rounded-xl sm:rounded-2xl border border-amber-500/20 bg-amber-500/5 select-none min-h-[96px]"
        >
          {header}
          <div className="flex-1 flex items-center justify-center">
            <span className="text-[9px] font-black uppercase tracking-tight text-amber-500 bg-amber-500/10 border border-amber-500/20 px-2 py-0.5 rounded-full leading-tight">
              NOT RUNNING
            </span>
          </div>
        </div>
      );
    }

    // ── 2b. TATKAL NOT OPEN STATE ──
    const isTatkalNotOpenReason = val && 'error' in val && val.reason === 'TATKAL_NOT_OPEN';
    if (dItem.isTatkalNotOpen || isTatkalNotOpenReason) {
      return (
        <div
          key={dItem.dateStr}
          className="flex flex-col justify-between p-2.5 sm:p-3 rounded-xl sm:rounded-2xl border border-amber-500/30 bg-amber-500/5 select-none min-h-[96px]"
          title="Tatkal booking opens 1 day prior at 10:00 AM (AC) / 11:00 AM (Non-AC)"
        >
          {header}
          <div className="flex-1 flex flex-col items-center justify-center text-center">
            <span className="text-[9px] font-black uppercase tracking-tight text-amber-600 dark:text-amber-400 bg-amber-500/10 border border-amber-500/25 px-2 py-0.5 rounded-full leading-tight">
              OPENS D-1
            </span>
            <span className="text-[8px] font-bold text-muted/80 mt-1">
              10 AM AC · 11 AM SL
            </span>
          </div>
        </div>
      );
    }

    // ── 3. LOADING STATE ──
    if (isLoading) {
      return (
        <div
          key={dItem.dateStr}
          className="flex flex-col justify-between p-2.5 sm:p-3 rounded-xl sm:rounded-2xl border border-subtle bg-card/60 select-none min-h-[96px] animate-pulse"
        >
          {header}
          <div className="space-y-2 mt-auto">
            <div className="h-3.5 bg-input/80 rounded-md w-3/4" />
            <div className="h-2.5 bg-input/60 rounded-md w-1/2" />
          </div>
        </div>
      );
    }

    // ── 4. LOADED DATA STATE ──
    if (val && !('error' in val)) {
      const cls = classifyAvailability(val.status, val.isCurrentBooking, val.currentBookingSeats);
      const isCurrAvbl = cls.isCurrAvbl;
      const currSeats = cls.currSeats;

      const isRegret = cls.isTerminal;
      const isWl = cls.isWaitlisted;
      const isRac = cls.isRac;
      const isCnf = cls.isAvailable || cls.isConfirmed;
      const isQuotaRegret = isRegret && qNorm !== 'GN';
      const isTatkalWl = isWl && qNorm === 'TQ';
      const quotaLabel = QUOTA_FULL_LABELS[qNorm] || qNorm;
      if (cls.isUnknown) {
        return (
          <button
            key={dItem.dateStr}
            type="button"
            onClick={() => handleDateClick(dItem)}
            className="flex flex-col justify-between p-2.5 sm:p-3 rounded-xl sm:rounded-2xl border border-amber-500/30 bg-amber-500/5 hover:bg-amber-500/10 select-none min-h-[96px] text-left cursor-pointer active:scale-[0.98] shadow-xs transition-all duration-200"
          >
            {header}
            <div className="flex items-center justify-between gap-1 mt-auto">
              <span className="text-[9px] font-black uppercase tracking-tight text-amber-600 dark:text-amber-400">
                Could not confirm availability
              </span>
              <span className="text-[10px] font-black text-primary hover:underline whitespace-nowrap">
                Retry ↻
              </span>
            </div>
          </button>
        );
      }
      const totalFare = val.fare
        ? (typeof val.fare === 'object' && val.fare !== null
            ? (val.fare.totalFare || val.fare.total_fare || val.fare.total)
            : val.fare)
        : null;

      return (
        <button
          key={dItem.dateStr}
          type="button"
          onClick={() => handleDateClick(dItem)}
          className={clsx(
            "flex flex-col justify-between p-2.5 sm:p-3 rounded-xl sm:rounded-2xl border shadow-xs transition-all duration-200 select-none min-h-[96px] text-left cursor-pointer active:scale-[0.98]",
            dItem.dateStr === date ? "ring-1 ring-primary/40 border-primary/40" : "",
            isCurrAvbl ? "border-emerald-500/50 bg-emerald-500/10 hover:bg-emerald-500/15" :
            isCnf ? "border-emerald-500/35 bg-emerald-500/5 hover:bg-emerald-500/10" :
            isWl ? "border-amber-500/35 bg-amber-500/5 hover:bg-amber-500/10" :
            isRac ? "border-blue-500/35 bg-blue-500/5 hover:bg-blue-500/10" :
            isRegret ? "border-rose-500/35 bg-rose-500/5 hover:bg-rose-500/10" :
            "border-slate-200/80 dark:border-slate-800 bg-card hover:bg-input/60"
          )}
        >
          {header}
          <div className="space-y-1 mt-auto">
            {isCurrAvbl && (
              <div className="inline-flex items-center gap-1 text-[8px] sm:text-[9px] font-black uppercase tracking-wider text-emerald-600 dark:text-emerald-300 bg-emerald-500/20 px-1.5 py-0.5 rounded-md border border-emerald-500/30 mb-0.5">
                ⚡ Current Booking
              </div>
            )}
            <span className={clsx(
              "block text-xs sm:text-sm font-black tracking-tight truncate leading-tight",
              (isCurrAvbl || isCnf) ? "text-emerald-600 dark:text-emerald-400" :
              isWl ? "text-amber-600 dark:text-amber-400" :
              isRac ? "text-blue-600 dark:text-blue-400" :
              isRegret ? "text-rose-600 dark:text-rose-400" :
              "text-main"
            )}>
              {isCurrAvbl && currSeats ? `CURR AVBL ${currSeats}` : isQuotaRegret ? `NO SEATS IN ${qNorm} QUOTA` : val.status}
            </span>
            {isTatkalWl && (
              <span className="text-[8px] sm:text-[9px] font-bold text-amber-600/90 dark:text-amber-400/90 block leading-none truncate" title="Tatkal Checked: Waiting List (Not Confirmed)">
                TATKAL CHECKED · WAITING LIST
              </span>
            )}
            {isQuotaRegret ? (
              <span className="text-[8px] sm:text-[9px] font-bold text-muted block leading-none truncate" title={`No berths allocated or available in ${quotaLabel} (${qNorm}) quota. You can try General (GN) quota.`}>
                Suggestion: Try General (GN)
              </span>
            ) : (
              <div className="flex items-center justify-between gap-1 text-[10px] sm:text-[11px] font-bold">
                {totalFare ? (
                  <span className="text-secondary font-mono">
                    ₹{totalFare}
                  </span>
                ) : <span />}
                {isCnf || isCurrAvbl ? (
                  <span className="text-[9px] sm:text-[10px] font-black text-emerald-600 dark:text-emerald-400">
                    AVAILABLE NOW · 100%
                  </span>
                ) : (isWl || isRac) && typeof val.chance === 'number' ? (
                  <span className={clsx(
                    "text-[9px] sm:text-[10px] font-black",
                    val.chance >= 75 ? "text-emerald-600 dark:text-emerald-400" :
                    val.chance >= 45 ? "text-amber-600 dark:text-amber-400" :
                    "text-rose-600 dark:text-rose-400"
                  )}>
                    {val.chance}% chance
                  </span>
                ) : null}
              </div>
            )}
          </div>
        </button>
      );
    }

    // ── 5. ERROR / UNAVAILABLE STATE (distinguishes not running, class n/a, provider rejection, busy) ──
    if (val && 'error' in val) {
      const reason = val.reason;
      if (reason === 'TATKAL_NOT_OPEN') {
        return (
          <div
            key={dItem.dateStr}
            className="flex flex-col justify-between p-2.5 sm:p-3 rounded-xl sm:rounded-2xl border border-amber-500/30 bg-amber-500/5 select-none min-h-[96px]"
            title="Tatkal booking opens 1 day prior at 10:00 AM (AC) / 11:00 AM (Non-AC)"
          >
            {header}
            <div className="flex-1 flex flex-col items-center justify-center text-center">
              <span className="text-[9px] font-black uppercase tracking-tight text-amber-600 dark:text-amber-400 bg-amber-500/10 border border-amber-500/25 px-2 py-0.5 rounded-full leading-tight">
                OPENS D-1
              </span>
              <span className="text-[8px] font-bold text-muted/80 mt-1">
                10 AM AC · 11 AM SL
              </span>
            </div>
          </div>
        );
      }
      const isNotRunning = reason === 'TRAIN_NOT_RUNNING';
      const isClassNa = reason === 'CLASS_NOT_AVAILABLE';
      const isRejected = reason === 'PROVIDER_REQUEST_REJECTED';
      const isBusy = reason === 'PROVIDER_UNAVAILABLE';
      const isUnknown = reason === 'AVAILABILITY_UNKNOWN' || val.type === 'unknown';
      const isNetwork = val.type === 'network';

      if (isNotRunning) {
        return (
          <div
            key={dItem.dateStr}
            className="flex flex-col justify-between p-2.5 sm:p-3 rounded-xl sm:rounded-2xl border border-amber-500/20 bg-amber-500/5 select-none min-h-[96px]"
          >
            {header}
            <div className="flex-1 flex items-center justify-center">
              <span className="text-[9px] font-black uppercase tracking-tight text-amber-500 bg-amber-500/10 border border-amber-500/20 px-2 py-0.5 rounded-full leading-tight">
                NOT RUNNING
              </span>
            </div>
          </div>
        );
      }

      if (isClassNa) {
        return (
          <div
            key={dItem.dateStr}
            className="flex flex-col justify-between p-2.5 sm:p-3 rounded-xl sm:rounded-2xl border border-subtle bg-input/20 select-none min-h-[96px]"
          >
            {header}
            <div className="flex-1 flex items-center justify-center">
              <span className="text-[9px] font-black uppercase tracking-tight text-muted/80 bg-input/40 border border-subtle px-2 py-0.5 rounded-full leading-tight">
                CLASS N/A
              </span>
            </div>
          </div>
        );
      }

      const errorLabel = isUnknown
        ? 'Could not confirm availability'
        : isRejected ? 'Provider Error' : isBusy ? 'Servers Busy' : isNetwork ? 'Network Error' : 'Unavailable';

      return (
        <button
          key={dItem.dateStr}
          type="button"
          onClick={() => handleDateClick(dItem)}
          className={clsx(
            "flex flex-col justify-between p-2.5 sm:p-3 rounded-xl sm:rounded-2xl select-none min-h-[96px] text-left cursor-pointer active:scale-[0.98] shadow-xs transition-all duration-200",
            isUnknown
              ? "border border-amber-500/30 bg-amber-500/5 hover:bg-amber-500/10"
              : "border border-rose-500/30 bg-rose-500/5 hover:bg-rose-500/10"
          )}
        >
          {header}
          <div className="flex items-center justify-between gap-1 mt-auto">
            <span className={clsx(
              "text-[9px] font-black uppercase tracking-tight truncate",
              isUnknown ? "text-amber-600 dark:text-amber-400" : "text-rose-500"
            )} title={val.message || errorLabel}>
              {errorLabel}
            </span>
            <span className="text-[10px] font-black text-primary hover:underline whitespace-nowrap">
              Retry ↻
            </span>
          </div>
        </button>
      );
    }

    // ── 6. UNCHECKED STATE (whole card is clickable) ──
    return (
      <button
        key={dItem.dateStr}
        type="button"
        onClick={() => handleDateClick(dItem)}
        className="flex flex-col justify-between p-2.5 sm:p-3 rounded-xl sm:rounded-2xl border border-dashed border-primary/30 bg-primary/5 hover:bg-primary/10 shadow-xs transition-all duration-200 cursor-pointer active:scale-[0.98] select-none min-h-[96px] text-left group/date"
      >
        {header}
        <div className="flex-1 flex items-center justify-center">
          <span className="text-[10px] sm:text-[11px] font-black text-primary group-hover/date:scale-[1.03] transition-transform uppercase tracking-wider">
            TAP TO CHECK
          </span>
        </div>
      </button>
    );
  };

  return (
    <div className="mt-4 pt-4 border-t border-slate-200/80 dark:border-slate-800">

      {/* ── SECTION LABEL ── */}
      <div className="flex items-center justify-between mb-2.5 px-0.5">
        <span className="text-[11px] font-black uppercase tracking-wider text-muted flex items-center gap-1.5 flex-wrap">
          <Calendar className="w-3.5 h-3.5 text-primary shrink-0" />
          <span>Check Availability</span>
          <span className={clsx(
            "text-[9px] font-black uppercase tracking-wider px-2 py-0.5 rounded-full border leading-none inline-flex items-center gap-1",
            qNorm === 'TQ' ? "bg-amber-500/10 text-amber-600 dark:text-amber-400 border-amber-500/25" :
            qNorm === 'LD' ? "bg-pink-500/10 text-pink-600 dark:text-pink-400 border-pink-500/25" :
            qNorm === 'SS' ? "bg-purple-500/10 text-purple-600 dark:text-purple-400 border-purple-500/25" :
            "bg-primary/10 text-primary border-primary/25"
          )}>
            Quota: {QUOTA_FULL_LABELS[qNorm] || qNorm}
          </span>
        </span>
        <span className="text-[9px] font-bold text-muted/70 uppercase tracking-widest">
          Select Class
        </span>
      </div>

      {/* ── PRIMARY: Modern Segmented Control Class Selector ── */}
      <div
        role="tablist"
        aria-label="Train travel classes"
        className="p-1 sm:p-1.5 bg-input/40 border border-subtle rounded-xl sm:rounded-2xl flex items-center gap-1 sm:gap-1.5 overflow-x-auto no-scrollbar touch-pan-x scroll-smooth mb-3.5"
      >
        {supportedClasses.map((cls) => {
          const isSelected = activeClass === cls;
          const searchDateAvail = getAvail(cls, date);
          const isClassNa = searchDateAvail && typeof searchDateAvail === 'object' && 'error' in searchDateAvail && (searchDateAvail as any).reason === 'CLASS_NOT_AVAILABLE';
          const availStatus = searchDateAvail && typeof searchDateAvail === 'object' && !('error' in searchDateAvail) && (searchDateAvail as any).status ? (searchDateAvail as any).status : null;
          const tabCls = classifyAvailability(availStatus);
          const isCnf = tabCls.isAvailable || tabCls.isConfirmed;
          const isWl = tabCls.isWaitlisted;

          return (
            <button
              key={cls}
              type="button"
              role="tab"
              aria-selected={isSelected}
              aria-disabled={isClassNa}
              onClick={() => handleClassClick(cls)}
              className={clsx(
                "flex-1 min-w-[50px] sm:min-w-[64px] shrink-0 sm:shrink min-h-[44px] h-11 sm:h-12 rounded-lg sm:rounded-xl text-center transition-all duration-200 flex flex-col items-center justify-center select-none relative",
                isClassNa
                  ? "opacity-40 text-muted/60 cursor-not-allowed bg-transparent line-through"
                  : isSelected
                  ? "bg-gradient-to-r from-blue-600 to-indigo-600 text-white font-black shadow-md shadow-blue-500/20 ring-1 ring-blue-500/40 cursor-pointer scale-[1.02]"
                  : "bg-transparent hover:bg-card/80 text-secondary hover:text-main font-bold active:scale-95 cursor-pointer border border-transparent hover:border-subtle"
              )}
              title={isClassNa ? `${cls} is not available for this route/date` : `View ${cls} availability across travel dates`}
            >
              <span className={clsx(
                "text-xs sm:text-sm font-black tracking-wider leading-none",
                isSelected ? "text-white" : isClassNa ? "text-muted/60" : "text-main"
              )}>
                {cls}
              </span>
              {isCnf && (
                <span className={clsx("text-[8px] font-bold mt-0.5 leading-none", isSelected ? "text-emerald-200" : "text-emerald-500")}>
                  AVL
                </span>
              )}
              {isWl && (
                <span className={clsx("text-[8px] font-bold mt-0.5 leading-none", isSelected ? "text-amber-200" : "text-amber-500")}>
                  WL
                </span>
              )}
            </button>
          );
        })}
      </div>

      {/* ── SECONDARY: Nearby dates label ── */}
      <p className="text-[9px] font-black uppercase tracking-widest text-muted/60 px-0.5 mb-2">
        Nearby Availability (4-Day Window)
      </p>

      {/* ── DATE AVAILABILITY CARDS: 2x2 mobile / 4-col desktop, each independently clickable ── */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-2 sm:gap-2.5">
        {dateWindow.map((dItem) => renderDateCard(dItem))}
      </div>

      {/* ── Current Booking IRCTC Disclaimer (Rendered ONLY when CURR_AVBL > 0 is present) ── */}
      {dateWindow.some((dItem) => {
        const v = getAvail(activeClass, dItem.dateStr);
        if (!v || typeof v !== 'object' || ('error' in v) || !v.status) return false;
        const m = v.status.match(/CURR(?:ENT)?[\s_-]*AV(?:B|AI)?L(?:ABLE)?[\s_-]*(\d+)?/i);
        const s = v.currentBookingSeats !== undefined ? v.currentBookingSeats : (m && m[1] ? parseInt(m[1], 10) : null);
        return (v.isCurrentBooking === true || Boolean(m)) && (s === null || s > 0);
      }) && (
        <div className="mt-2.5 px-3 py-1.5 rounded-xl bg-emerald-500/10 border border-emerald-500/25 flex items-center justify-between gap-2 text-[10px] text-emerald-700 dark:text-emerald-300">
          <div className="flex items-center gap-1.5 font-medium">
            <span className="font-bold">⚡ Live data from IRCTC PRS.</span>
            <span className="text-secondary dark:text-emerald-400/80">Subject to real-time booking on IRCTC.</span>
          </div>
          <span className="text-[9px] uppercase font-bold tracking-widest text-emerald-600 dark:text-emerald-400 shrink-0">
            First-Come First-Served
          </span>
        </div>
      )}
    </div>
  );
};
