'use client';

import React, { useState, useEffect } from 'react';
import { Share2, Gift, Users, Copy, Zap, Loader2, Check } from 'lucide-react';
import { getInviteStats, claimReferral } from '@/lib/api';
import { clsx } from 'clsx';
import { shareToWhatsApp } from '@/lib/share';
import { getReferralLink } from '@/config/domains';

export function ReferralSection() {
  const [stats, setStats] = useState<any>(null);
  const [claimCode, setClaimCode] = useState('');
  const [loading, setLoading] = useState(true);
  const [claiming, setClaiming] = useState(false);
  const [copied, setCopied] = useState(false);
  const [message, setMessage] = useState<{ type: 'success' | 'error', text: string } | null>(null);

  useEffect(() => {
    fetchStats();
    
    // Auto-fill claimCode from URL if ?ref= is present and valid
    if (typeof window !== 'undefined') {
      const searchParams = new URLSearchParams(window.location.search);
      const ref = searchParams.get('ref');
      // Validate referral code (alphanumeric and dashes, 4-20 chars)
      if (ref && /^[A-Z0-9-]{4,20}$/i.test(ref)) {
        setClaimCode(ref.toUpperCase());
      }
    }
  }, []);

  const fetchStats = async () => {
    try {
      const res = await getInviteStats('');
      if (res.success) setStats(res.data);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleClaim = async () => {
    if (!claimCode) return;
    setClaiming(true);
    setMessage(null);
    try {
      const sid = localStorage.getItem('trayago_session');
      const res = await claimReferral(sid || '', claimCode);
      if (res.success) {
        setMessage({ type: 'success', text: 'Referral claimed! Free check added.' });
        setClaimCode('');
        fetchStats();
      } else {
        setMessage({ type: 'error', text: res.message || 'Invalid code' });
      }
    } catch (err) {
      setMessage({ type: 'error', text: 'Failed to claim code' });
    } finally {
      setClaiming(false);
    }
  };

  const handleShare = () => {
    const code = stats?.referral_code || 'RAIL-GUEST';
    const text = `🚆 Track my live train, PNR updates & smart split tickets on Trayago.\n\n` +
                 `Join here: https://trayago.in?ref=${code}\n` +
                 `Use my referral code: ${code}`;
    shareToWhatsApp(text);
  };

  const copyToClipboard = async () => {
    const code = stats?.referral_code || 'RAIL-GUEST';
    await navigator.clipboard.writeText(code);
    setCopied(true);
    setTimeout(() => setCopied(false), 1500);
  };

  if (loading) return <div className="animate-pulse bg-input h-32 rounded-3xl" />;

  return (
    <div className="w-full space-y-4">
      <div className="bg-card p-8 rounded-[2.5rem] border border-subtle space-y-8 relative overflow-hidden group">
         <div className="absolute top-0 right-0 p-6 opacity-5 rotate-12 group-hover:scale-110 transition-transform duration-700">
            <Gift size={100} className="text-emerald-500" />
         </div>

         <div className="space-y-1 relative z-10">
             <div className="flex items-center space-x-2 text-blue-600 dark:text-blue-400 text-[10px] font-black uppercase tracking-[0.2em]">
                <Zap size={14} className="fill-blue-600 dark:fill-blue-400" />
                <span>Rewards</span>
             </div>
             <h3 className="text-2xl font-black tracking-tighter text-main">Unlock FREE AI Rescue by Inviting Friends</h3>
            <p className="text-muted text-xs font-medium">1 Invite = 1 Free PNR Check. 5 Invites = 3 Days Blitz PRO.</p>
         </div>

         {/* Stats Row */}
         <div className="grid grid-cols-2 gap-3 relative z-10">
            <div className="bg-input p-4 rounded-2xl border border-subtle space-y-1">
               <p className="text-muted text-[8px] font-black uppercase tracking-widest leading-none">Your Invites</p>
               <div className="flex items-center space-x-2">
                  <span className="text-xl font-black text-main">{stats?.referral_count || 0}</span>
                  <Users size={14} className="text-muted" />
               </div>
            </div>
            <div className="bg-input p-4 rounded-2xl border border-subtle space-y-1">
               <p className="text-muted text-[8px] font-black uppercase tracking-widest leading-none">Your Code</p>
               <button 
                 onClick={copyToClipboard}
                 className="flex items-center space-x-2 group/code bg-card px-2 py-0.5 rounded-lg border border-subtle hover:bg-input transition-colors"
               >
                   <span className="text-sm font-black text-emerald-600 dark:text-emerald-400 font-mono tracking-tighter">{stats?.referral_code || 'RAIL-GUEST'}</span>
                   {copied ? <Check size={10} className="text-emerald-600 dark:text-emerald-400" /> : <Copy size={10} className="text-muted group-hover/code:text-main transition-colors" />}
               </button>
            </div>
         </div>

         {/* Share Button */}
         <button
           onClick={handleShare}
            className="w-full py-4 rounded-2xl bg-blue-600 hover:bg-blue-700 text-white flex items-center justify-center space-x-3 transition-all active:scale-[0.98] shadow-sm text-xs font-black uppercase tracking-[0.15em]"
         >
           <Share2 size={18} />
           <span>Invite on WhatsApp</span>
         </button>

         {/* Claim Section */}
         <div className="pt-6 border-t border-subtle space-y-4">
            <p className="text-xs font-black text-muted uppercase tracking-widest ml-2">Got a referral code?</p>
            <div className="flex space-x-2">
               <input 
                 type="text" 
                 placeholder="RAIL-XXXX"
                 value={claimCode}
                 onChange={(e) => setClaimCode(e.target.value.toUpperCase())}
                 className="flex-1 bg-input border border-subtle rounded-2xl py-3 px-5 text-sm font-bold text-main outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500/30 transition-all placeholder:text-muted font-mono"
               />
               <button
                 onClick={handleClaim}
                 disabled={!claimCode || claiming}
                 className={clsx(
                   "px-6 rounded-2xl flex items-center justify-center transition-all active:scale-95",
                   claiming || !claimCode ? "bg-input text-muted" : "bg-main text-card font-black uppercase text-[10px] tracking-widest"
                 )}
               >
                 {claiming ? <Loader2 className="animate-spin" size={16} /> : 'Claim'}
               </button>
            </div>
            {message && (
               <p className={clsx(
                 "text-[9px] font-bold uppercase tracking-widest text-center",
                 message.type === 'success' ? 'text-emerald-400' : 'text-red-400'
               )}>
                 {message.text}
               </p>
            )}
         </div>
      </div>
    </div>
  );
}
