'use client';

import React, { useState, useEffect, useCallback, useSyncExternalStore } from 'react';
import { createPortal } from 'react-dom';
import { useRouter } from 'next/navigation';
import { ShieldCheck, Smartphone, AlertCircle, Calendar, ArrowRight, Clock, X, CheckCircle2, UserCheck } from 'lucide-react';
import { useVerificationStatus } from '@/hooks/useVerificationStatus';

export interface GateTrigger {
  isGated: boolean;
  errorCode?: string;
  message?: string;
  action?: string;
  deadline?: string;
  requiredFields?: string[];
}

interface StoredModalUser {
  id?: string;
  isAdmin?: boolean;
  planType?: string;
  mobileVerified?: boolean;
  mobileVerification?: { verified?: boolean };
}

interface MobileVerificationReminderModalProps {
  gateTrigger?: GateTrigger | null;
  onClose?: () => void;
  onModalStateChange?: (isOpen: boolean) => void;
}

const emptySubscribe = () => () => {};

export default function MobileVerificationReminderModal({
  gateTrigger,
  onClose,
  onModalStateChange
}: MobileVerificationReminderModalProps) {
  const router = useRouter();
  const isClient = useSyncExternalStore(
    emptySubscribe,
    () => true,
    () => false
  );

  const [isOpen, setIsOpen] = useState(false);
  const { status: authStatus, isEligibleForReminder, isMobileVerified: hookVerified } = useVerificationStatus();
  const status = authStatus;

  const updateOpenState = useCallback((open: boolean) => {
    setIsOpen(open);
    if (onModalStateChange) {
      onModalStateChange(open);
    }
  }, [onModalStateChange]);

  // Check user verification status on mount or when gateTrigger changes
  useEffect(() => {
    if (!isClient) return;

    // 1. If explicitly triggered in gated mode from search error, open immediately
    if (gateTrigger && gateTrigger.isGated) {
      const timer = setTimeout(() => {
        updateOpenState(true);
      }, 0);
      return () => clearTimeout(timer);
    }

    // 2. If user is already verified, do not show
    if (hookVerified || authStatus?.isMobileVerified) {
      const timer = setTimeout(() => {
        updateOpenState(false);
      }, 0);
      return () => clearTimeout(timer);
    }

    // 3. Otherwise evaluate progressive reminder for logged-in users during grace period
    const checkReminder = async () => {
      try {
        const userStr = localStorage.getItem('user');
        const token = localStorage.getItem('accessToken');
        if (!userStr || !token) {
          // Guest user: never show mobile verification reminder
          return;
        }

        let user: StoredModalUser | null = null;
        try {
          user = JSON.parse(userStr) as StoredModalUser;
        } catch {
          return;
        }

        // Admins are always exempt from mobile verification reminders
        if (user?.isAdmin || user?.planType === 'admin') {
          return;
        }

        const isLocalVerified = Boolean(user?.mobileVerified || user?.mobileVerification?.verified);
        // If local user is already verified for mobile, skip reminder check
        if (isLocalVerified) {
          return;
        }

        // Check 24-hour snooze state in localStorage
        const snoozedUntilStr = localStorage.getItem('trayago_verify_reminder_snoozed_until');
        if (snoozedUntilStr) {
          const snoozedUntil = parseInt(snoozedUntilStr, 10);
          if (Date.now() < snoozedUntil) {
            // Still in snooze window: do not nag user
            return;
          }
        }

        // Only prompt if eligible for reminder and mobile is NOT verified
        if (isEligibleForReminder && authStatus && !authStatus.isMobileVerified && !authStatus.isGated) {
          const timer = setTimeout(() => {
            updateOpenState(true);
          }, 2000);
          return () => clearTimeout(timer);
        }
      } catch {
        // Silently skip if offline
      }
    };

    checkReminder();
  }, [isClient, gateTrigger, hookVerified, authStatus, isEligibleForReminder, updateOpenState]);

  const localUserVerified = (() => {
    if (typeof window === 'undefined') return false;
    try {
      const u = JSON.parse(localStorage.getItem('user') || '{}') as StoredModalUser;
      return Boolean(u.mobileVerified || u.mobileVerification?.verified);
    } catch {
      return false;
    }
  })();

  const isMandatoryGate = Boolean(gateTrigger?.isGated);
  const isMobileVerified = status?.isMobileVerified ?? hookVerified ?? localUserVerified;
  const isMobilePending = gateTrigger
    ? gateTrigger.errorCode !== 'PROFILE_COMPLETION_REQUIRED'
    : !isMobileVerified;

  const handleDismiss = () => {
    // Snooze reminder for 24 hours so it does not pop up repeatedly
    const snoozeUntil = Date.now() + 24 * 60 * 60 * 1000;
    try {
      localStorage.setItem('trayago_verify_reminder_snoozed_until', String(snoozeUntil));
    } catch {}
    updateOpenState(false);
    if (onClose) onClose();
  };

  const handleAction = () => {
    updateOpenState(false);
    if (onClose) onClose();
    if (isMobilePending) {
      router.push('/profile?action=verify-mobile');
    } else {
      router.push('/profile');
    }
  };

  if (!isClient || !isOpen) return null;

  const deadlineFormatted = gateTrigger?.deadline 
    ? new Date(gateTrigger.deadline).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' })
    : (status?.deadline ? new Date(status.deadline).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' }) : 'Nov 8, 2026');

  const daysLeft = status?.daysRemaining !== undefined ? status.daysRemaining : 14;

  return createPortal(
    <div 
      className="fixed inset-0 z-[9999] flex items-center justify-center p-4 bg-black/75 backdrop-blur-md animate-fade-in"
      role="dialog"
      aria-modal="true"
      aria-labelledby="verify-modal-title"
    >
      {/* Click outside to dismiss (disabled during mandatory gate) */}
      <div 
        className="absolute inset-0" 
        onClick={isMandatoryGate ? undefined : handleDismiss} 
      />

      <div className="relative w-full max-w-lg bg-card/95 border border-subtle backdrop-blur-2xl rounded-3xl p-6 md:p-8 shadow-2xl overflow-hidden z-10 animate-scale-up">
        {/* Glow decorative backdrop */}
        <div className="absolute -top-24 -right-24 w-60 h-60 bg-primary/10 rounded-full blur-3xl pointer-events-none" />
        <div className="absolute -bottom-24 -left-24 w-60 h-60 bg-blue-500/10 rounded-full blur-3xl pointer-events-none" />

        {/* Close Button: only available if not a mandatory gate */}
        {!isMandatoryGate && (
          <button
            onClick={handleDismiss}
            className="absolute top-5 right-5 p-2 rounded-full text-muted hover:text-main hover:bg-input transition-colors cursor-pointer z-20"
            aria-label="Dismiss"
            title="Dismiss"
          >
            <X className="w-5 h-5" />
          </button>
        )}

        {/* Header Badge */}
        <div className="flex items-center gap-2 mb-4">
          <div className={`p-2.5 rounded-2xl border ${isMandatoryGate ? 'bg-amber-500/15 border-amber-500/30 text-amber-500' : 'bg-primary/15 border-primary/30 text-primary'}`}>
            <ShieldCheck className="w-6 h-6" />
          </div>
          <div>
            <div className="flex items-center gap-2">
              <span className={`text-[10px] font-black uppercase tracking-wider px-2 py-0.5 rounded-full border ${isMandatoryGate ? 'bg-amber-500/10 border-amber-500/25 text-amber-500' : 'bg-primary/10 border-primary/25 text-primary'}`}>
                {isMandatoryGate ? 'Action Required' : 'Account Security Policy'}
              </span>
              {!isMandatoryGate && daysLeft > 0 && (
                <span className="text-[10px] font-bold text-muted flex items-center gap-1">
                  <Clock className="w-3 h-3 text-primary animate-pulse" />
                  {daysLeft} days left in grace period
                </span>
              )}
            </div>
            <h2 id="verify-modal-title" className="text-xl md:text-2xl font-display font-black tracking-tight text-main mt-1">
              {isMandatoryGate 
                ? (isMobilePending ? 'Verify Mobile to Continue' : 'Complete Profile to Continue')
                : (isMobilePending ? 'Verify Mobile & Profile' : 'Complete Passenger Profile')}
            </h2>
          </div>
        </div>

        {/* Policy Description */}
        <p className="text-sm text-muted leading-relaxed mb-5">
          {!isMobilePending ? (
            <span>
              Your mobile number is verified. To ensure seamless IRCTC train ticket booking readiness, please complete your passenger profile (Full Name, Date of Birth, and Gender) before <strong className="text-main">{deadlineFormatted}</strong>.
            </span>
          ) : isMandatoryGate ? (
            <span>
              The 14-day policy deadline expired on <strong className="text-main">{deadlineFormatted}</strong>. Under Trayago&apos;s account-security and booking policy, authenticated search access requires mobile OTP verification and passenger profile completion.
            </span>
          ) : (
            <span>
              Under Trayago&apos;s account-security and booking policy, all passenger accounts must verify their mobile number and complete their profile before <strong className="text-main">{deadlineFormatted}</strong>.
            </span>
          )}
        </p>

        {/* Requirements Checklist Card */}
        <div className="bg-input/40 border border-subtle rounded-2xl p-4 mb-6 space-y-2.5">
          <div className="text-xs font-black uppercase tracking-wider text-muted mb-1 flex items-center justify-between">
            <span>Required for Railway Booking Readiness</span>
            <span className="text-primary font-bold">IRCTC Standard</span>
          </div>

          <div className="flex items-center justify-between text-xs py-1 border-b border-subtle/50">
            <span className="flex items-center gap-2 text-main font-medium">
              <Smartphone className="w-4 h-4 text-primary" />
              Mobile OTP Verification
            </span>
            {(status?.isMobileVerified || !isMobilePending) ? (
              <span className="text-emerald-500 font-bold flex items-center gap-1">
                <CheckCircle2 className="w-3.5 h-3.5" /> Verified
              </span>
            ) : (
              <span className="text-amber-500 font-bold flex items-center gap-1">
                <AlertCircle className="w-3.5 h-3.5" /> Pending OTP
              </span>
            )}
          </div>

          <div className="flex items-center justify-between text-xs py-1 border-b border-subtle/50">
            <span className="flex items-center gap-2 text-main font-medium">
              <UserCheck className="w-4 h-4 text-primary" />
              Full Name (as per Gov ID)
            </span>
            {status?.isProfileComplete || (status?.missingFields && !status.missingFields.includes('fullName')) ? (
              <span className="text-emerald-500 font-bold flex items-center gap-1">
                <CheckCircle2 className="w-3.5 h-3.5" /> Complete
              </span>
            ) : (
              <span className="text-amber-500 font-bold flex items-center gap-1">
                <AlertCircle className="w-3.5 h-3.5" /> Required
              </span>
            )}
          </div>

          <div className="flex items-center justify-between text-xs py-1 border-b border-subtle/50">
            <span className="flex items-center gap-2 text-main font-medium">
              <Calendar className="w-4 h-4 text-primary" />
              Date of Birth &amp; Gender (M / F / T)
            </span>
            {status?.isProfileComplete || (status?.missingFields && !status.missingFields.includes('dob') && !status.missingFields.includes('gender')) ? (
              <span className="text-emerald-500 font-bold flex items-center gap-1">
                <CheckCircle2 className="w-3.5 h-3.5" /> Complete
              </span>
            ) : (
              <span className="text-amber-500 font-bold flex items-center gap-1">
                <AlertCircle className="w-3.5 h-3.5" /> Required
              </span>
            )}
          </div>
        </div>

        {/* Action Buttons */}
        <div className="flex flex-col sm:flex-row items-center gap-3">
          <button
            onClick={handleAction}
            className="w-full sm:flex-1 py-3 px-5 rounded-2xl bg-primary text-white font-bold text-sm hover:brightness-110 active:scale-[0.98] transition-all flex items-center justify-center gap-2 shadow-lg shadow-primary/20"
          >
            <span>
              {isMandatoryGate 
                ? (isMobilePending ? 'Verify Mobile & Unlock Search' : 'Complete Profile & Unlock Search')
                : (isMobilePending ? 'Verify Mobile Now' : 'Complete Profile Now')}
            </span>
            <ArrowRight className="w-4 h-4" />
          </button>

          {!isMandatoryGate && (
            <button
              onClick={handleDismiss}
              className="w-full sm:w-auto py-3 px-4 rounded-2xl bg-input hover:bg-input/80 text-muted hover:text-main font-semibold text-sm transition-all"
            >
              Remind Me Later
            </button>
          )}
        </div>

        {/* Security / Privacy Assurance */}
        <p className="text-[11px] text-muted text-center mt-4">
          {isMobilePending 
            ? '🔒 Secure 6-digit OTP verification. We never collect Aadhaar, PAN, or passport numbers.'
            : '🔒 Passenger details are required for IRCTC booking compliance. We never collect Aadhaar, PAN, or passport numbers.'}
        </p>
      </div>
    </div>,
    document.body
  );
}
